    const { job_id, bike_id, station_id, depot, source, fault } = job;
    addJob.run(job_id, bike_id, station_id, depot, source, fault, reportedAt, openedAt);
    disableBike.run(station_id, bike_id);
  }
}

export function openDatabase(): Database {
  const isNew = !existsSync(DATABASE_FILE);
  const database = new Database(DATABASE_FILE);
  if (isNew) {
    database.exec(TABLES);
    fillStationsAndBikes(database);
    fillOpenJobs(database);
  }
  return database;
}
// The public feed in GBFS v3 shape: https://github.com/MobilityData/gbfs/blob/master/gbfs.md
// Rider apps and the city read it. The contract says it must be accurate at all times.
import type { Database } from "bun:sqlite";

const FEED_VERSION = "3.0";
const SECONDS_UNTIL_STALE = 60;

type BikeRow = { bike_id: string; bike_type: string; station_id: string; is_disabled: number };
type StationCount = { station_id: string; docks: number; available: number; disabled: number };

function wrapInFeed(data: object) {
  const lastUpdated = new Date().toISOString();
  return { last_updated: lastUpdated, ttl: SECONDS_UNTIL_STALE, version: FEED_VERSION, data };
}

export function vehicleStatus(database: Database) {
  const bikes = database.query("SELECT * FROM bikes ORDER BY bike_id").all() as BikeRow[];
  const vehicles = bikes.map((bike) => ({
    vehicle_id: bike.bike_id,
    station_id: bike.station_id,
    vehicle_type_id: bike.bike_type,
    is_reserved: false,
    is_disabled: bike.is_disabled === 1,
  }));
  return wrapInFeed({ vehicles });
}

const STATION_COUNTS = `
  SELECT stations.station_id, stations.docks,
    SUM(CASE WHEN bikes.is_disabled = 0 THEN 1 ELSE 0 END) AS available,
    SUM(CASE WHEN bikes.is_disabled = 1 THEN 1 ELSE 0 END) AS disabled
  FROM stations LEFT JOIN bikes ON bikes.station_id = stations.station_id
  GROUP BY stations.station_id ORDER BY stations.station_id`;

export function stationStatus(database: Database) {
  const counts = database.query(STATION_COUNTS).all() as StationCount[];
  const stations = counts.map((count) => ({
    station_id: count.station_id,
    num_vehicles_available: count.available ?? 0,
    num_vehicles_disabled: count.disabled ?? 0,
    num_docks_available: Math.max(0, count.docks - (count.available ?? 0) - (count.disabled ?? 0)),
    is_renting: true,
    is_returning: true,
  }));
  return wrapInFeed({ stations });
}
// spoke: Kestrel's service. It serves the public feed, takes wrench reports and lists crew jobs.
// Start it with: bun run world
import { crewQueue } from "./crew-queue";
import { openDatabase } from "./database";
import { stationStatus, vehicleStatus } from "./feed";
import { mapPage } from "./map-page";
import { recordWrench } from "./wrenches";

const PORT = Number(process.env.PORT ?? 4100);
const database = openDatabase();

const asJson = (body: unknown, status = 200) => Response.json(body, { status });

async function handleWrench(request: Request): Promise<Response> {
  const report = await request.json().catch(() => ({}));
  const outcome = recordWrench(database, report);
  return asJson(outcome.body, outcome.status);
}

function handleQueue(request: Request): Response {
  const depot = new URL(request.url).searchParams.get("depot");
  return asJson(crewQueue(database, depot));
}

const server = Bun.serve({
  port: PORT,
  routes: {
    "/": () => new Response(mapPage(database), { headers: { "content-type": "text/html" } }),
    "/health": () => asJson({ ok: true }),
    "/gbfs/v3/vehicle_status.json": () => asJson(vehicleStatus(database)),
    "/gbfs/v3/station_status.json": () => asJson(stationStatus(database)),
    "/wrench": { POST: handleWrench },
    "/crew/queue": handleQueue,
  },
  fetch: () => asJson({ error: "no such page" }, 404),
});

console.log(`spoke is running on http://localhost:${server.port}`);
// AC-1: WHEN a rider sends POST /wrench for a bike,
// THEN vehicle_status.json shows that bike with is_disabled: true within 60 seconds.
import { afterAll, expect, test } from "bun:test";
import { becomesTrue, getJson, startSpoke, wrench } from "./spoke";

const spoke = await startSpoke();
afterAll(() => spoke.stop());

type Vehicle = { vehicle_id: string; is_disabled: boolean };

async function isDisabled(bikeId: string): Promise<boolean> {
  const feed = await getJson(`${spoke.url}/gbfs/v3/vehicle_status.json`);
  const bike = (feed.data.vehicles as Vehicle[]).find((vehicle) => vehicle.vehicle_id === bikeId);
  return bike?.is_disabled === true;
}

test("AC-1: a wrenched bike shows is_disabled: true in the feed", async () => {
  expect(await isDisabled("B-2207")).toBe(false);
  await wrench(spoke.url, "B-2207");
  // The contract allows 60 seconds. spoke should take far less, so the test waits 5.
  expect(await becomesTrue(() => isDisabled("B-2207"), 5)).toBe(true);
}, 10_000);
// AC-2: WHEN a rider wrenches a bike at a station,
// THEN station_status.json shows num_vehicles_disabled for that station up by 1 within 60 seconds.
import { afterAll, expect, test } from "bun:test";
import { becomesTrue, getJson, startSpoke, wrench } from "./spoke";

const spoke = await startSpoke();
afterAll(() => spoke.stop());

type Vehicle = { vehicle_id: string; station_id: string };
type Station = { station_id: string; num_vehicles_disabled: number };

async function disabledAt(stationId: string): Promise<number> {
  const feed = await getJson(`${spoke.url}/gbfs/v3/station_status.json`);
  const stations = feed.data.stations as Station[];
  return stations.find((station) => station.station_id === stationId)?.num_vehicles_disabled ?? 0;
}

test("AC-2: the station's disabled count goes up by one", async () => {
  const feed = await getJson(`${spoke.url}/gbfs/v3/vehicle_status.json`);
  const bike = (feed.data.vehicles as Vehicle[]).find((vehicle) => vehicle.vehicle_id === "B-1500");
  const stationId = bike?.station_id ?? "";
  const before = await disabledAt(stationId);
  await wrench(spoke.url, "B-1500");
  const countWentUp = async () => (await disabledAt(stationId)) === before + 1;
  expect(await becomesTrue(countWentUp, 5)).toBe(true);
}, 10_000);
// AC-3: WHEN a crew asks for GET /crew/queue?depot=North,
// THEN the jobs come back ordered by deadline, the job due first on top.
import { afterAll, expect, test } from "bun:test";
import { getJson, startSpoke } from "./spoke";

const spoke = await startSpoke();
afterAll(() => spoke.stop());

type Job = { job_id: string; deadline: string };

test("AC-3: the North queue is ordered by deadline", async () => {
  const queue = await getJson(`${spoke.url}/crew/queue?depot=North`);
  const deadlines = (queue.jobs as Job[]).map((job) => Date.parse(job.deadline));
  const sorted = [...deadlines].sort((first, second) => first - second);
  expect(deadlines.length).toBeGreaterThan(1);
  expect(deadlines).toEqual(sorted);
});
// AC-4: WHEN a job comes from a wrench,
// THEN its deadline is 48 hours after the wrench reported_at: the clock starts at the wrench.
import { afterAll, expect, test } from "bun:test";
import { getJson, startSpoke } from "./spoke";

const spoke = await startSpoke();
afterAll(() => spoke.stop());

const HOUR = 60 * 60 * 1000;

type Job = { source: string; reported_at: string; opened_at: string; deadline: string };

test("AC-4: a wrench job is due 48 hours after the wrench", async () => {
  const queue = await getJson(`${spoke.url}/crew/queue`);
  const wrenchJobs = (queue.jobs as Job[]).filter((job) => job.source === "wrench");
  expect(wrenchJobs.length).toBeGreaterThan(0);
  for (const job of wrenchJobs) {
    const expected = Date.parse(job.reported_at) + 48 * HOUR;
    expect(Date.parse(job.deadline)).toBe(expected);
  }
});
// Starts a fresh spoke for one test file and talks to it over HTTP, the way the rider app does.
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export type Spoke = { url: string; stop: () => void };

export async function startSpoke(): Promise<Spoke> {
  const scratch = mkdtempSync(join(tmpdir(), "spoke-acceptance-"));
  const port = 5100 + Math.floor(Math.random() * 800);
  const environment = {
    ...process.env,
    PORT: String(port),
    SPOKE_DB: join(scratch, "spoke.db"),
    SPOKE_LOG: join(scratch, "spoke.log"),
  };
  const server = Bun.spawn(["bun", "src/server.ts"], { env: environment, stdout: "ignore" });
  const url = `http://localhost:${port}`;
  for (let attempt = 0; attempt < 50; attempt++) {
    const healthy = await fetch(`${url}/health`).then(
      (response) => response.ok,
      () => false,
    );
    if (healthy) return { url, stop: () => server.kill() };
    await Bun.sleep(200);
  }
  server.kill();
  throw new Error("spoke did not start");
}

export async function getJson(url: string) {
  const response = await fetch(url);
  return response.json();
}

export async function wrench(url: string, bikeId: string, requestId?: string) {
  const body = JSON.stringify({ bike_id: bikeId, fault: "BATT", request_id: requestId });
  return fetch(`${url}/wrench`, { method: "POST", body });
}

// Asks again every half second until the answer is true or the time is up.
export async function becomesTrue(question: () => Promise<boolean>, seconds: number) {
  const giveUpAt = Date.now() + seconds * 1000;
  while (Date.now() < giveUpAt) {
    if (await question()) return true;
    await Bun.sleep(500);
  }
  return false;
}
// Action item A-1 from work/postmortem.md: a retry with the same request_id is one report.
// In the incident, the app sent each report up to 3 times and 212 bikes got duplicate jobs.
import { afterAll, expect, test } from "bun:test";
import { getJson, startSpoke, wrench } from "../acceptance/spoke";

const spoke = await startSpoke();
afterAll(() => spoke.stop());

type Job = { bike_id: string };

test("A-1: three retries of one wrench open one job", async () => {
  for (let retry = 0; retry < 3; retry++) await wrench(spoke.url, "B-2400", "request-77");
  const queue = await getJson(`${spoke.url}/crew/queue`);
  const jobsForBike = (queue.jobs as Job[]).filter((job) => job.bike_id === "B-2400");
  expect(jobsForBike).toHaveLength(1);
});
# The service levels in Kestrel's contract with Brannock City Transport.
# The shape follows the service levels in Citi Bike's monthly report to New York City:
# https://mot-marketing-whitelabel-prod.s3.us-east-1.amazonaws.com/nyc/April-2026-Citi-Bike-Monthly-Report.pdf
# Nobody edits this file except the city. Claude Code must never change it.
contract: Brannock City Transport and Kestrel Bike Share
service_levels:
  - id: SLA-4
    name: Bike defects
    rule: A rider pressing the wrench button is notice of a defect.
    clock_starts: when the rider reports the defect (the wrench)
    wrenched_limit_hours: 48
    not_wrenched_limit_hours: 96
    target_percent: 95
    credit_per_late_bike_gbp: 50
  - id: SLA-9
    name: Bike availability
    rule: The share of the fleet that riders can rent, across every district.
    minimum_percent: 96
  - id: SLA-11
    name: Station outage
    rule: No single station outage lasts longer than this.
    limit_hours: 4
  - id: SLA-12
    name: Public feed accuracy
    rule: Real-time data in the public feed is accurate and available to the public at all times.
    feed_max_age_seconds: 60
